x;bottom:18px}.content{padding:28px;min-width:0}.topbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:24px}.identity{display:flex;align-items:center;gap:10px}.avatar{width:34px;height:34px;border-radius:9px;background:#1c2a3a;display:grid;place-items:center;font-weight:700}.summary-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:18px}.summary-card{padding:17px}.summary-value{font-size:26px;font-weight:750}.summary-label{color:var(--m);margin-top:4px}.workspace{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(300px,.75fr);gap:16px}.panel-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:13px}.panel-title h2{margin:0;font-size:17px}.permission-line{display:grid;grid-template-columns:minmax(130px,1fr) minmax(120px,1fr) minmax(100px,.7fr) minmax(100px,.7fr) auto;gap:10px;align-items:center;padding:11px 0;border-bottom:1px solid var(--l)}.permission-line:last-child{border-bottom:0}.subject-type{color:var(--m);font-size:11px}.chip{display:inline-flex;padding:4px 8px;border-radius:999px;background:#192534;border:1px solid #293a4e;font-size:11px}.muted{color:var(--m)}.object-tabs{display:flex;gap:6px;margin-bottom:14px;flex-wrap:wrap}.object-tab.active{background:var(--a);color:#07111b}.object-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.object-item{display:flex;align-items:center;gap:10px;padding:11px;border:1px solid var(--l);border-radius:9px;background:#0d131b}.object-main{flex:1;min-width:0}.object-main strong,.object-main small{display:block}.object-main small{color:var(--m);margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.compact-form{display:grid;gap:10px}.compact-form .form-row{grid-template-columns:1fr 1fr}.inline-form{display:flex;gap:8px;align-items:end}.inline-form label{flex:1;margin:0}.danger{color:#f0a5ad}.plain-form{margin:0}.section{margin-bottom:18px}.explain{padding:12px 14px;background:#0c121a;border-left:3px solid var(--a);color:var(--m);margin-bottom:14px}.matrix-table td:first-child{font-weight:650}.empty{padding:22px;text-align:center;color:var(--m)}@media(max-width:950px){.shell{grid-template-columns:1fr}.sidebar{position:static;height:auto;border-right:0;border-bottom:1px solid var(--l)}.nav-group{grid-template-columns:repeat(5,1fr)}.sidebar-foot{position:static;margin-top:12px}.content{padding:18px}.workspace{grid-template-columns:1fr}.summary-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){.nav-group{grid-template-columns:1fr 1fr}.summary-grid,.object-grid{grid-template-columns:1fr}.permission-line{grid-template-columns:1fr 1fr}.permission-line form{grid-column:2}.inline-form{display:grid}.content{padding:12px}}@media(max-width:700px){.directory-layout{grid-template-columns:1fr}.directory-picker{grid-template-columns:1fr 1fr}.form-row{grid-template-columns:1fr}.directory-option{padding:10px}.directory-option small{display:none}}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body>';if($error)echo'<div class="error">'.h($error).'</div>';}
if(!$u){head('Anmeldung');echo'<main class="login"><section class="box"><h1>'.($first?'Ersteinrichtung':'Anmelden').'</h1>';if($step==='setup-totp'){$pu=one('SELECT * FROM users WHERE id=?',[$_SESSION['pending']??'']);$s=$_SESSION['secret']??'';$uri='otpauth://totp/'.rawurlencode('CAG:'.$pu['username']).'?secret='.$s.'&issuer=CAG';$q=qr($uri);echo'<p>QR scannen oder Schlüssel kopieren, dann Code bestätigen.</p>'.($q?'<img style="width:220px;background:white;padding:8px;display:block;margin:auto" src="'.h($q).'">':'').'<input id="secret" readonly value="'.h($s).'"><button onclick="navigator.clipboard.writeText(secret.value)">Kopieren</button><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="setup-totp"><label>Code<input name="code" pattern="[0-9]{6}" required></label><button class="primary">Bestätigen</button></form>';}elseif($step==='totp'){echo'<form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="totp"><label>TOTP-Code<input name="code" pattern="[0-9]{6}" autofocus required></label><button class="primary">Anmelden</button></form>';}elseif($first){echo'<form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="setup"><label>Benutzername<input name="username" required></label><label>Passwort<input type="password" name="password" required></label><label>Interne Adresse<input type="url" name="url" value="http://localhost/" required></label><button class="primary">Anlegen</button></form>';}else{echo'<form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="login"><input type="hidden" name="sys" value="'.h($sys).'"><label>Benutzername<input name="username" autofocus required></label><label>Passwort<input type="password" name="password" required></label><button class="primary">Anmelden</button></form>';}echo'</section></main></body></html>';exit;}
$view=$_GET['view']??($u['admin']?'dashboard':'account');
if($u['must_password'])$view='account';
head('CAG');
$nav=['dashboard'=>'Übersicht','users'=>'Benutzer','permissions'=>'Berechtigungen','ldap'=>'Verzeichnisdienste','audit'=>'Audit'];
echo'<div class="shell"><aside class="sidebar"><div class="brand-block"><strong>Central Auth</strong><small>Zentrale Identitäten</small></div><nav class="nav-group">';
if($u['admin']&&!$u['must_password'])foreach($nav as $key=>$label)echo'<a class="nav-link '.($view===$key?'active':'').'" href="?view='.$key.'"><span class="nav-dot"></span>'.h($label).'</a>';
echo'<a class="nav-link '.($view==='account'?'active':'').'" href="?view=account"><span class="nav-dot"></span>Konto</a></nav><div class="sidebar-foot"><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="logout"><button style="width:100%">Abmelden</button></form></div></aside><main class="content"><header class="topbar"><div></div><div class="identity"><div class="avatar">'.h(strtoupper(substr($u['username'],0,1))).'</div><div><strong>'.h($u['username']).'</strong><div class="muted">'.($u['admin']?'Administrator':'Benutzer').'</div></div></div></header>';
if($f=$_SESSION['flash']??''){echo'<div class="card section">'.h($f).'</div>';unset($_SESSION['flash']);}

if($view==='dashboard'&&$u['admin']){
    $stats=['Benutzer'=>(int)one('SELECT COUNT(*) c FROM users')['c'],'Gruppen'=>(int)one('SELECT COUNT(*) c FROM groups')['c'],'Zielsysteme'=>(int)one('SELECT COUNT(*) c FROM systems WHERE internal=0')['c'],'Berechtigungen'=>(int)one('SELECT COUNT(*) c FROM assignments')['c']];
    echo'<div class="page-head"><div><h1>Übersicht</h1><p class="muted">Zentrale Konten, Systeme und wirksame Zuweisungen.</p></div></div><div class="summary-grid">';foreach($stats as $label=>$value)echo'<div class="card summary-card"><div class="summary-value">'.$value.'</div><div class="summary-label">'.h($label).'</div></div>';echo'</div>';
    $recent=rows("SELECT a.*,s.name system_name,r.name role_name,t.name tenant_name,CASE WHEN a.subject_type='user' THEN u.username ELSE g.name END subject_name FROM assignments a JOIN systems s ON s.id=a.system_id LEFT JOIN roles r ON r.id=a.role_id LEFT JOIN tenants t ON t.id=a.tenant_id LEFT JOIN users u ON a.subject_type='user' AND u.id=a.subject_id LEFT JOIN groups g ON a.subject_type='group' AND g.id=a.subject_id WHERE s.internal=0 ORDER BY a.rowid DESC LIMIT 8");
    echo'<div class="workspace"><section class="card"><div class="panel-title"><h2>Letzte Berechtigungen</h2><a class="btn" href="?view=permissions">Alle verwalten</a></div>';if(!$recent)echo'<div class="empty">Noch keine Berechtigungen angelegt.</div>';foreach($recent as $x)echo'<div class="permission-line"><div><strong>'.h($x['subject_name']).'</strong><div class="subject-type">'.($x['subject_type']==='user'?'Benutzer':'Gruppe').'</div></div><div>'.h($x['system_name']).'</div><div><span class="chip">'.h($x['role_name']?:'ohne Rolle').'</span></div><div>'.h($x['tenant_name']?:'ohne Tenant').'</div><span></span></div>';echo'</section><aside class="card"><div class="panel-title"><h2>Logik</h2></div><div class="explain">Ein Benutzer erhält Berechtigungen direkt oder über seine Gruppen. Rolle und Tenant gelten immer für das ausgewählte Zielsystem.</div><a class="btn primary" href="?view=permissions">Berechtigung anlegen</a></aside></div>';
}
elseif($view==='account'){
    echo'<div class="page-head"><div><h1>Mein Konto</h1><p class="muted">Passwort und persönliches Icon.</p></div></div><div class="workspace">';
    if($u['source']==='local')echo'<form class="card compact-form" method="post"><div class="panel-title"><h2>'.($u['must_password']?'Passwort jetzt ändern':'Passwort ändern').'</h2></div><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="password"><label>Aktuelles Passwort<input type="password" name="old" required></label><label>Neues Passwort<input type="password" name="new" minlength="10" required></label><button class="primary">Passwort speichern</button></form>';
    if(!$u['must_password'])echo'<form class="card compact-form" method="post" enctype="multipart/form-data"><div class="panel-title"><h2>Icon</h2></div><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="user_icon"><label>PNG oder JPG<input type="file" name="icon" accept="image/png,image/jpeg" required></label><button>Icon speichern</button></form>';echo'</div>';
}
elseif($view==='users'&&$u['admin']){
    $gen=$_SESSION['generated']??'';unset($_SESSION['generated']);if($gen)echo'<div class="card password-result"><div><span class="muted">Neues Initialpasswort</span><strong id="generated-password">'.h($gen).'</strong></div><button type="button" onclick="copyText(document.getElementById(\'generated-password\').textContent,this)">Kopieren</button></div>';
    echo'<div class="page-head"><div><h1>Benutzer</h1><p class="muted">Lokale und synchronisierte Konten.</p></div><button class="primary" type="button" onclick="openUserDialog()">+ Benutzer</button></div><div class="card table-wrap"><table><tr><th>Benutzer</th><th>Quelle</th><th>Admin</th><th>MFA</th><th>Passwortwechsel</th><th></th></tr>';
    foreach(rows('SELECT * FROM users ORDER BY username') as $x){$data=h(json_encode(['id'=>$x['id'],'username'=>$x['username'],'admin'=>(bool)$x['admin'],'mfa'=>(bool)$x['mfa_required'],'must'=>(bool)$x['must_password']],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT));echo'<tr><td><div class="user-cell">'.($x['icon']?'<img class="icon" src="?kind=users&icon='.h($x['icon']).'">':'').'<strong>'.h($x['username']).'</strong></div></td><td>'.h($x['source']).'</td><td>'.($x['admin']?'Ja':'Nein').'</td><td>'.($x['mfa_required']?'Pflicht':'Optional').'</td><td>'.($x['must_password']?'Ausstehend':'Nein').'</td><td class="row-actions"><button type="button" onclick="openUserDialog(JSON.parse(this.dataset.user))" data-user="'.$data.'">Bearbeiten</button><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="reset"><input type="hidden" name="id" value="'.h($x['id']).'"><button>Reset</button></form></td></tr>';}
    echo'</table></div><dialog id="user-dialog"><div class="dialog-head"><div><h2 id="user-dialog-title">Benutzer anlegen</h2><p class="muted">Anmeldedaten und Sicherheitsvorgaben.</p></div><button type="button" class="icon-button" onclick="userDialog.close()">×</button></div><form method="post" id="user-form" class="dialog-form"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="save_user"><input type="hidden" name="id"><label>Benutzername<input name="username" required></label><label>Passwort<div class="password-line"><input type="password" name="password"><button type="button" onclick="generateAndCopyPassword(this)">Erzeugen & kopieren</button></div></label><div id="password-copy-note" class="copy-note" hidden></div><div class="checks"><label><input type="checkbox" name="admin"> Administrator</label><label><input type="checkbox" name="mfa"> TOTP verpflichtend</label><label><input type="checkbox" name="must" onchange="enforcePasswordChanged(this)"> Passwortwechsel beim ersten Login</label></div><div class="dialog-actions"><button type="button" onclick="userDialog.close()">Abbrechen</button><button class="primary">Speichern</button></div></form></dialog>';
}
elseif($view==='permissions'&&$u['admin']){
    $users=rows('SELECT id,username name FROM users WHERE active=1 ORDER BY username');$groups=rows('SELECT id,name FROM groups ORDER BY name');$roles=rows('SELECT id,name FROM roles ORDER BY name');$tenants=rows('SELECT id,name FROM tenants ORDER BY name');$systems=rows('SELECT id,name,url FROM systems WHERE internal=0 ORDER BY name');
    $assignments=rows("SELECT a.*,s.name system_name,r.name role_name,t.name tenant_name,CASE WHEN a.subject_type='user' THEN u.username ELSE g.name END subject_name FROM assignments a JOIN systems s ON s.id=a.system_id LEFT JOIN roles r ON r.id=a.role_id LEFT JOIN tenants t ON t.id=a.tenant_id LEFT JOIN users u ON a.subject_type='user' AND u.id=a.subject_id LEFT JOIN groups g ON a.subject_type='group' AND g.id=a.subject_id WHERE s.internal=0 ORDER BY s.name,subject_name");
    $members=rows('SELECT m.user_id,m.group_id,u.username,g.name group_name FROM memberships m JOIN users u ON u.id=m.user_id JOIN groups g ON g.id=m.group_id ORDER BY g.name,u.username');
    echo'<div class="page-head"><div><h1>Berechtigungen</h1><p class="muted">Systeme, Gruppen, Rollen, Tenants und ihre wirksamen Beziehungen.</p></div></div><div class="explain"><strong>Lesart:</strong> Subjekt → Zielsystem → Rolle → Tenant. Gruppen vererben ihre Zuweisungen an alle Mitglieder.</div><div class="workspace"><section><div class="card section"><div class="panel-title"><h2>Berechtigung zuweisen</h2></div><form method="post" class="compact-form"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="assign"><div class="form-row"><label>Gilt für<select name="subject_type" id="subject-type" onchange="updateSubjects()"><option value="user">Benutzer</option><option value="group">Gruppe</option></select></label><label>Benutzer oder Gruppe<select name="subject" id="subject-select"></select></label></div><div class="form-row"><label>Zielsystem<select name="system" required>';foreach($systems as $x)echo'<option value="'.$x['id'].'">'.h($x['name']).'</option>';echo'</select></label><label>Rolle<select name="role"><option value="">Keine Rolle</option>';foreach($roles as $x)echo'<option value="'.$x['id'].'">'.h($x['name']).'</option>';echo'</select></label></div><label>Tenant<select name="tenant"><option value="">Kein Tenant</option>';foreach($tenants as $x)echo'<option value="'.$x['id'].'">'.h($x['name']).'</option>';echo'</select></label><button class="primary">Berechtigung speichern</button></form></div><div class="card"><div class="panel-title"><h2>Aktuelle Zuweisungen</h2><span class="count-badge">'.count($assignments).'</span></div>';if(!$assignments)echo'<div class="empty">Noch keine Berechtigungen.</div>';foreach($assignments as $x)echo'<div class="permission-line"><div><strong>'.h($x['subject_name']).'</strong><div class="subject-type">'.($x['subject_type']==='user'?'Benutzer':'Gruppe').'</div></div><div><strong>'.h($x['system_name']).'</strong></div><div><span class="chip">'.h($x['role_name']?:'ohne Rolle').'</span></div><div>'.h($x['tenant_name']?:'ohne Tenant').'</div><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="assignment_delete"><input type="hidden" name="id" value="'.h($x['id']).'"><button class="danger">Entfernen</button></form></div>';echo'</div></section><aside><div class="card section"><div class="panel-title"><h2>Gruppenmitglieder</h2></div><form method="post" class="compact-form"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="membership"><label>Benutzer<select name="user">';foreach($users as $x)echo'<option value="'.$x['id'].'">'.h($x['name']).'</option>';echo'</select></label><label>Gruppe<select name="group">';foreach($groups as $x)echo'<option value="'.$x['id'].'">'.h($x['name']).'</option>';echo'</select></label><button>Mitglied hinzufügen</button></form>';foreach($members as $m)echo'<div class="permission-line" style="grid-template-columns:1fr 1fr auto"><span>'.h($m['username']).'</span><span class="chip">'.h($m['group_name']).'</span><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="membership_delete"><input type="hidden" name="user" value="'.$m['user_id'].'"><input type="hidden" name="group" value="'.$m['group_id'].'"><button class="danger">×</button></form></div>';echo'</div><div class="card"><div class="panel-title"><h2>Stammdaten</h2></div><div class="object-tabs">';foreach(['systems'=>'Systeme','groups'=>'Gruppen','roles'=>'Rollen','tenants'=>'Tenants'] as $key=>$label)echo'<button type="button" class="object-tab '.($key==='systems'?'active':'').'" onclick="showObjectPanel(\''.$key.'\',this)">'.$label.'</button>';echo'</div>';
    foreach(['systems'=>$systems,'groups'=>$groups,'roles'=>$roles,'tenants'=>$tenants] as $type=>$items){echo'<div class="object-panel" data-panel="'.$type.'" '.($type==='systems'?'':'hidden').' ><form method="post" class="compact-form"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="save_entity"><input type="hidden" name="type" value="'.$type.'"><input type="hidden" name="id"><label>Name<input name="name" required></label>';if($type==='systems')echo'<label>Ziel-URL<input type="url" name="url" required></label>';echo'<button>Anlegen</button></form><div class="object-grid" style="margin-top:12px">';foreach($items as $x)echo'<div class="object-item"><div class="object-main"><strong>'.h($x['name']).'</strong>'.($type==='systems'?'<small>'.h($x['url']).'</small>':'').'</div><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="entity_delete"><input type="hidden" name="type" value="'.$type.'"><input type="hidden" name="id" value="'.$x['id'].'"><button class="danger">×</button></form></div>';echo'</div></div>';}
    echo'</div></aside></div><script>window.permissionSubjects='.json_encode(['user'=>$users,'group'=>$groups],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).';</script>';
}
elseif($view==='ldap'&&$u['admin']){
    $sources=rows('SELECT * FROM ldap_sources ORDER BY provider,name');echo'<div class="page-head"><div><h1>Verzeichnisdienste</h1><p class="muted">Active Directory und LDAP konfigurieren.</p></div></div><div class="directory-layout"><aside class="directory-picker"><button type="button" class="directory-option active" data-provider="ad" onclick="selectDirectoryProvider(\'ad\')"><span class="provider-mark">AD</span><span><strong>Active Directory</strong><small>Windows-Domäne</small></span></button><button type="button" class="directory-option" data-provider="ldap" onclick="selectDirectoryProvider(\'ldap\')"><span class="provider-mark">L</span><span><strong>LDAP</strong><small>OpenLDAP / LDAP</small></span></button></aside><section class="card directory-form"><div class="section-heading"><h2 id="directory-title">Active Directory</h2><span class="status-badge">Neu</span></div><form method="post" class="form-stack" id="directory-form"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="ldap"><input type="hidden" name="id"><input type="hidden" name="provider" value="ad"><div class="form-row"><label>Name<input name="name" value="Active Directory" required></label><label>Server-URI<input name="uri" value="ldap://dc01.example.org:389" required></label></div><label>Base DN<input name="base_dn" placeholder="DC=example,DC=org" required></label><div class="form-row"><label>Bind DN<input name="bind_dn"></label><label>Bind-Passwort<input type="password" name="bind_password"></label></div><label>Benutzerfilter<input name="filter" value="(sAMAccountName={username})" required></label><div class="switch-list"><label class="switch-row"><span>StartTLS</span><input type="checkbox" name="tls" checked></label><label class="switch-row"><span>Aktiv</span><input type="checkbox" name="active" checked></label></div><div class="dialog-actions"><button type="button" onclick="resetDirectoryForm()">Leeren</button><button class="primary">Speichern</button></div></form></section></div><section class="saved-section"><div class="panel-title"><h2>Verbindungen</h2><span class="count-badge">'.count($sources).'</span></div><div class="integration-list">';if(!$sources)echo'<div class="empty">Keine Verbindung eingerichtet.</div>';foreach($sources as $x){$data=h(json_encode(['id'=>$x['id'],'provider'=>$x['provider']??'ldap','name'=>$x['name'],'uri'=>$x['uri'],'base_dn'=>$x['base_dn'],'bind_dn'=>$x['bind_dn'],'filter'=>$x['user_filter'],'tls'=>(bool)$x['start_tls'],'active'=>(bool)$x['active']],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT));echo'<button type="button" class="integration-item" data-source="'.$data.'" onclick="editDirectorySource(JSON.parse(this.dataset.source))"><span class="provider-mark">'.(($x['provider']??'ldap')==='ad'?'AD':'L').'</span><span class="integration-main"><strong>'.h($x['name']).'</strong><small>'.h($x['uri']).'</small></span><span class="connection-state '.($x['active']?'enabled':'disabled').'">'.($x['active']?'Aktiv':'Inaktiv').'</span></button>'; }echo'</div></section>';
}
elseif($view==='audit'&&$u['admin']){echo'<div class="page-head"><div><h1>Audit</h1><p class="muted">Sicherheitsrelevante Aktionen.</p></div></div><div class="card table-wrap"><table><tr><th>Zeit</th><th>Akteur</th><th>Aktion</th></tr>';foreach(rows('SELECT * FROM audit ORDER BY id DESC LIMIT 300') as $x)echo'<tr><td>'.date('Y-m-d H:i:s',$x['ts']).'</td><td>'.h($x['actor']).'</td><td>'.h($x['action']).'</td></tr>';echo'</table></div>';}
echo'</main></div>';
echo <<<'HTML'
</main><script>
const userDialog=document.getElementById('user-dialog');
function openUserDialog(user={}){const f=document.getElementById('user-form');f.reset();f.id.value=user.id||'';f.username.value=user.username||'';f.admin.checked=!!user.admin;f.mfa.checked=!!user.mfa;f.must.checked=!!user.must;f.password.required=!user.id;document.getElementById('user-dialog-title').textContent=user.id?'Benutzer bearbeiten':'Benutzer anlegen';document.getElementById('password-copy-note').hidden=true;userDialog.showModal()}
function securePassword(){const chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@$%+-_';const bytes=new Uint32Array(16);crypto.getRandomValues(bytes);return Array.from(bytes,x=>chars[x%chars.length]).join('')}
async function copyText(value,button){try{await navigator.clipboard.writeText(value);if(button){const old=button.textContent;button.textContent='Kopiert';setTimeout(()=>button.textContent=old,1200)}return true}catch{return false}}
async function generateAndCopyPassword(button){const input=document.querySelector('#user-form [name=password]');input.value=securePassword();input.type='text';input.focus();input.select();const copied=await copyText(input.value,button);const note=document.getElementById('password-copy-note');note.hidden=false;note.textContent=copied?'Passwort wurde erzeugt und kopiert.':'Passwort wurde erzeugt. Zum Kopieren markieren.'}
function enforcePasswordChanged(box){if(!box.checked)return;const input=document.querySelector('#user-form [name=password]');if(!input.value)generateAndCopyPassword(box)}

function selectDirectoryProvider(provider){
  const form=document.getElementById('directory-form');
  if(!form)return;
  form.provider.value=provider;
  document.querySelectorAll('.directory-option').forEach(button=>button.classList.toggle('active',button.dataset.provider===provider));
  const ad=provider==='ad';
  document.getElementById('directory-title').textContent=ad?'Active Directory anbinden':'LDAP anbinden';
  document.getElementById('directory-subtitle').textContent=ad?'Für eine interne Windows-Domäne mit verschlüsselter Verbindung.':'Für OpenLDAP oder einen allgemeinen LDAP-Verzeichnisdienst.';
  if(!form.id.value){
    form.name.value=ad?'Interne Active Directory':'Interner LDAP-Server';
    form.uri.value=ad?'ldap://dc01.example.org:389':'ldap://ldap.example.org:389';
    form.filter.value=ad?'(sAMAccountName={username})':'(uid={username})';
  }
}
function resetDirectoryForm(){
  const form=document.getElementById('directory-form');
  if(!form)return;
  const provider=form.provider.value||'ad';
  form.reset();form.id.value='';form.provider.value=provider;
  document.querySelector('.status-badge').textContent='Neue Verbindung';
  selectDirectoryProvider(provider);
}
function editDirectorySource(source){
  const form=document.getElementById('directory-form');
  selectDirectoryProvider(source.provider||'ldap');
  form.id.value=source.id||'';form.name.value=source.name||'';form.uri.value=source.uri||'';form.base_dn.value=source.base_dn||'';form.bind_dn.value=source.bind_dn||'';form.bind_password.value='';form.filter.value=source.filter||'';form.tls.checked=!!source.tls;form.active.checked=!!source.active;
  document.querySelector('.status-badge').textContent='Verbindung bearbeiten';
  form.scrollIntoView({behavior:'smooth',block:'start'});
}

function updateSubjects(){const type=document.getElementById('subject-type');const select=document.getElementById('subject-select');if(!type||!select||!window.permissionSubjects)return;select.innerHTML=(window.permissionSubjects[type.value]||[]).map(item=>`<option value="${item.id}">${item.name}</option>`).join('')}
function showObjectPanel(name,button){document.querySelectorAll('.object-panel').forEach(panel=>panel.hidden=panel.dataset.panel!==name);document.querySelectorAll('.object-tab').forEach(tab=>tab.classList.remove('active'));button.classList.add('active')}
document.addEventListener('DOMContentLoaded',updateSubjects);
</script></body></html>
HTML;
